async function requestUpload(userId, filename, contentType) {
  const key = `uploads/${userId}/${ids.next()}-${filename}`;

  const url = await storage.presign({
    key, contentType, method: 'PUT', expiresIn: 300,
  });

  await db.uploads.insert({ key, userId, status: 'pending' });
  return { uploadUrl: url, key };
}

async function initMultipart(key, contentType) {
  const { uploadId } = await storage.createMultipartUpload({ key, contentType });
  return uploadId;   // client requests a presigned URL per part, per this id
}

async function completeMultipart(key, uploadId, parts) {
  // parts: [{ partNumber, etag }, ...] returned by each part's PUT
  return storage.completeMultipartUpload({ key, uploadId, parts });
}

async function onUploadComplete(key) {
  const renditions = ['1080p', '720p', '480p', 'thumbnail'];

  await Promise.all(renditions.map((r) =>
    jobs.enqueue('transcode', { sourceKey: key, rendition: r })
  ));
}

async function playbackUrl(mediaId, preferred) {
  const ready = await db.renditions.ready(mediaId);   // e.g. ['480p','thumbnail']
  const rendition = ready.includes(preferred) ? preferred : ready[0];
  if (!rendition) return null;   // still processing, show a placeholder

  return cdn.urlFor(mediaId, rendition);
}
